#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


run_wizard() {

TOTAL_STAGES=9
REPO="v1be-coding/v1be-infra"
ACTIONS_URL="https://github.com/$REPO/actions/workflows/oidc-check.yml"
WORKFLOW=".github/workflows/oidc-check.yml"
DRAFT="/c/code/v1be-infra/.drafts/oidc-check.yml"
TEST_BRANCH="oidc-test"
export AWS_PROFILE="v1be-admin"
# Stops Git Bash rewriting the paths passed to gh api.
export MSYS_NO_PATHCONV=1

# GitHub owner logins stay in Windows Sandbox (ADR-0012).
if [[ ! -d /c/code/v1be-infra/sandbox ]]; then
  warn "Stopping: this isn't Windows Sandbox. Open v1be-admin.wsb and run it there."
  exit 1
fi

# open_pr BRANCH MESSAGE [delete] commits the workflow to a new branch, then opens a PR.
open_pr() {
  local branch="$1" message="$2" action="${3:-add}" main_sha file_sha pr_url
  main_sha="$(gh api "repos/$REPO/git/ref/heads/main" --jq .object.sha | tr -d '\r')"
  gh api -X POST "repos/$REPO/git/refs" -f "ref=refs/heads/$branch" -f "sha=$main_sha" >/dev/null
  if [[ "$action" == "delete" ]]; then
    file_sha="$(gh api "repos/$REPO/contents/$WORKFLOW" --jq .sha | tr -d '\r')"
    gh api -X DELETE "repos/$REPO/contents/$WORKFLOW" -f "message=$message" -f "branch=$branch" -f "sha=$file_sha" >/dev/null
  else
    gh api -X PUT "repos/$REPO/contents/$WORKFLOW" -f "message=$message" -f "branch=$branch" \
      -f "content=$(base64 -w0 "$DRAFT")" >/dev/null
  fi
  pr_url="$(gh pr create --repo "$REPO" --head "$branch" --base main --title "$message" \
    --body "Temporary check for the accounts stack (phase C)." | tr -d '\r')"
  open_url "$pr_url"
}

# set_ids ARGS... sets both account IDs as secrets, where gh's ARGS say.
set_ids() {
  printf '%s' "$PORTFOLIO_ID" | gh secret set PORTFOLIO_ACCOUNT_ID --repo "$REPO" "$@"
  printf '%s' "$CAFE_ID" | gh secret set CAFE_ACCOUNT_ID --repo "$REPO" "$@"
}

banner "Check who can sign in to the v1be-infra CI roles"

stage "Before you start"
say "Run accounts-apply.sh for both accounts first."
say "This proves main's plan and apply jobs get in, and that nothing else does."
note "The workflow is temporary, because only the push-to-main workflow may name"
note "an environment. The last stages remove it."
pause

stage "Sign in to AWS and GitHub"
step "A browser opens. Sign in as v1be-admin and allow the request."
aws sso login --profile "$AWS_PROFILE"
PORTFOLIO_ID="$(aws organizations list-accounts --query "Accounts[?Name=='portfolio'].Id | [0]" --output text | tr -d '\r')"
CAFE_ID="$(aws organizations list-accounts --query "Accounts[?Name=='collective-cafe-prod'].Id | [0]" --output text | tr -d '\r')"
if [[ ! "$PORTFOLIO_ID" =~ ^[0-9]{12}$ || ! "$CAFE_ID" =~ ^[0-9]{12}$ ]]; then
  warn "Stopping: couldn't find both member accounts."
  exit 1
fi
step "Sign in with your own GitHub account, the org owner."
gh auth login --hostname github.com --git-protocol https --web --scopes admin:org,repo,workflow
ORG_ROLE="$(gh api user/memberships/orgs/v1be-coding --jq .role 2>/dev/null | tr -d '\r' || true)"
if [[ "$ORG_ROLE" != "admin" ]]; then
  warn "Stopping: this GitHub login isn't a v1be-coding owner."
  exit 1
fi
say "PASS: signed in to both"
pause

stage "Store the account IDs as secrets"
note "IDs stay out of this public repo, and secrets are masked in its public logs."
note "The plan and apply environments keep theirs for the edge stack."
set_ids --env plan
set_ids --env apply
note "A branch job can't see environment secrets, so it needs a repo-level copy."
note "That copy is only for this check, and stage 8 deletes it."
set_ids
say "PASS: secrets set"
pause

stage "Add the workflow"
if gh api "repos/$REPO/contents/$WORKFLOW" >/dev/null 2>&1; then
  say "It's already on main."
else
  step "Read $DRAFT first."
  confirm "Open a PR adding it?" || { warn "Stopping. Run this again when ready."; exit 1; }
  open_pr add-oidc-check "Add a temporary OIDC check"
  step "Wait for risky-text, then merge the PR in the browser."
  pause "Press Enter once it's merged."
fi
pause

stage "Run it from main"
gh workflow run oidc-check.yml --repo "$REPO" --ref main
open_url "$ACTIONS_URL"
step "Open the new run. The apply job waits for you, so approve it."
note "This also tests that apply gets its secrets only after approval."
say "Expected, all green:"
note "  with-environment (plan)   its own role allowed, the other refused"
note "  with-environment (apply)  the same, once you approve"
note "  no-environment            all four roles refused"
step "If a job fails, copy its 'Token sub' line and the failing line for Claude."
confirm "Did all three jobs pass?" || { warn "Stopping. Tell Claude which job failed. The repo-level IDs stay until a run reaches stage 8."; exit 1; }
pause

stage "Run it from a branch"
if ! gh api "repos/$REPO/git/ref/heads/$TEST_BRANCH" >/dev/null 2>&1; then
  MAIN_SHA="$(gh api "repos/$REPO/git/ref/heads/main" --jq .object.sha | tr -d '\r')"
  gh api -X POST "repos/$REPO/git/refs" -f "ref=refs/heads/$TEST_BRANCH" -f "sha=$MAIN_SHA" >/dev/null
fi
gh workflow run oidc-check.yml --repo "$REPO" --ref "$TEST_BRANCH"
open_url "$ACTIONS_URL"
say "Expected for this run:"
note "  with-environment (both)   RED: GitHub refuses, as the branch can't deploy there"
note "  no-environment            green, because all four roles were refused"
step "A red environment job is the pass here. It must fail before any step runs."
confirm "Did the run match that?" || { warn "Stopping. Tell Claude what differed. The repo-level IDs stay until a run reaches stage 8."; exit 1; }
pause

stage "Tell Claude the sub format"
step "From the main run, copy the 'Token sub' line from with-environment (plan)."
note "It holds only public GitHub names and IDs, so it's safe to share."
pause

stage "Remove the repo-level secrets and test branch"
gh secret delete PORTFOLIO_ACCOUNT_ID --repo "$REPO"
gh secret delete CAFE_ACCOUNT_ID --repo "$REPO"
gh api -X DELETE "repos/$REPO/git/refs/heads/$TEST_BRANCH" >/dev/null
say "PASS: both removed"
pause

stage "Remove the workflow"
open_pr remove-oidc-check "Remove the temporary OIDC check" delete
step "Wait for risky-text, then merge the PR in the browser."
pause "Press Enter once it's merged."

finish
say "Tell Claude the check passed, with the Token sub line."
note "Don't share account IDs."
}

run_wizard "$@"; exit
